/* greet — bundled demo package for fix.
 * Compile-time bakes in a banner generated by the `banner` package,
 * demonstrating cross-package build dependencies.
 */
#include <stdio.h>
#include <stdlib.h>

#ifndef GREET_BANNER_FILE
#define GREET_BANNER_FILE ""
#endif

int main(int argc, char **argv)
{
    FILE *f;
    int c;
    const char *who = (argc > 1 && argv[1][0]) ? argv[1] : "friend";

    f = fopen(GREET_BANNER_FILE, "r");
    if (f) {
        while ((c = fgetc(f)) != EOF)
            putchar(c);
        fclose(f);
    } else if (GREET_BANNER_FILE[0] != '\0') {
        /* A baked-in banner path that cannot be opened is a build/packaging
         * problem, not a reason to silently print a bare greeting. */
        fprintf(stderr, "greet: warning: cannot open banner file '%s'\n",
                GREET_BANNER_FILE);
    }
    printf("greetings, %s!\n", who);
    return 0;
}
